// Example of good server component pattern
interface Product {
  id: string | number;
  name: string;
}

export default function ProductList({ products }: { products: Product[] }) {
  return (
    <div>
      <h2>Products</h2>
      {products.map((product: Product) => (
        <div key={product.id}>{product.name}</div>
      ))}
    </div>
  );
}

import ProductList from './ProductList';
import UserProfile from './UserProfile';

// Example of existing server component with data fetching
async function getProducts() {
  try {
    const res = await fetch('/api/products');
    return res.json();
  } catch {
    // Return mock data for build time
    return [{ id: 1, name: 'Sample Product' }];
  }
}

export default async function Page() {
  const products = await getProducts();

  return (
    <div>
      <h1>Dashboard</h1>
      <ProductList products={products} />
      <UserProfile />
    </div>
  );
}

interface UserProfileData {
  name: string;
  email: string;
}

async function getUserProfile(): Promise<UserProfileData> {
  try {
    const res = await fetch('/api/users/profile');
    if (!res.ok) {
      throw new Error('Failed to fetch user profile');
    }
    return res.json();
  } catch {
    // Return mock data for build time
    return { name: 'Sample User', email: 'sample@example.com' };
  }
}

export default async function UserProfile() {
  const user = await getUserProfile();

  return (
    <div>
      <h2>User Profile</h2>
      <div>Name: {user.name}</div>
      <div>Email: {user.email}</div>
    </div>
  );
}
